"""Operaciones reproducibles sin credenciales incrustadas."""
COMPANY='mutation($input:CreateCompanyInput!){createCompany(input:$input){id name isActive}}'
ADMIN='mutation($input:CreateCompanyAdminInput!){createCompanyAdmin(input:$input){id userId companyId isAdmin user{id email}}}'
USER='mutation($actor:ID!,$input:CreateCompanyUserInput!){createCompanyUser(actorCompanyUserId:$actor,input:$input){id userId isAdmin}}'
LOGIN='mutation($input:LoginInput!){login(input:$input){token tokenType user{id email}}}'
ROLES='query($actor:ID!){roles(actorCompanyUserId:$actor){id code name description isActive} permissions(actorCompanyUserId:$actor){id code name description isActive}}'
MATRIX='query($actor:ID!,$role:ID!){rolePermissions(actorCompanyUserId:$actor,roleId:$role){id isActive role{code} permission{id code isActive}}}'
ASSIGN_ROLE='mutation($actor:ID!,$input:AssignRoleInput!){assignRole(actorCompanyUserId:$actor,input:$input){id isActive role{id code} companyUser{id companyId isAdmin}}}'
ADD_PERMISSION='mutation($actor:ID!,$input:AssignPermissionToRoleInput!){assignPermissionToRole(actorCompanyUserId:$actor,input:$input){id isActive role{code} permission{code}}}'
REMOVE_PERMISSION='mutation($actor:ID!,$role:ID!,$permission:ID!){removePermissionFromRole(actorCompanyUserId:$actor,roleId:$role,permissionId:$permission)}'
ACCOUNT='mutation($actor:ID!,$input:CreateAccountInput!){createAccount(actorCompanyUserId:$actor,input:$input){id companyId name accountType bankName accountNumber clabe cardLastDigits shortDescription longDescription isActive createdAt updatedAt company{id}}}'
CONCEPT='mutation($actor:ID!,$input:CreateConceptInput!){createConcept(actorCompanyUserId:$actor,input:$input){id companyId name conceptType shortDescription longDescription isActive createdAt updatedAt}}'
LINK='mutation($actor:ID!,$input:AssignConceptToAccountInput!){assignConceptToAccount(actorCompanyUserId:$actor,input:$input){id isActive createdAt account{id} concept{id}}}'
REMOVE_LINK='mutation($actor:ID!,$a:ID!,$c:ID!){removeConceptFromAccount(actorCompanyUserId:$actor,accountId:$a,conceptId:$c)}'
TX='mutation($actor:ID!,$input:CreateTransactionInput!){createTransaction(actorCompanyUserId:$actor,input:$input){id amount transactionType transactionDate capturedAt capturedBy isActive account{id} concept{id} capturedByUser{id}}}'
TXS='query($actor:ID!,$a:ID,$type:TransactionType,$limit:Int,$offset:Int){transactions(actorCompanyUserId:$actor,accountId:$a,transactionType:$type,limit:$limit,offset:$offset){id amount isActive capturedBy}}'
DELETE='mutation($actor:ID!,$id:ID!){deleteTransaction(actorCompanyUserId:$actor,id:$id){id isActive amount}}'
BALANCE='query($actor:ID!,$a:ID!){accountBalance(actorCompanyUserId:$actor,accountId:$a)}'
CREATE_ROLE='mutation($actor:ID!,$input:CreateRoleInput!){createRole(actorCompanyUserId:$actor,input:$input){id code name description isActive}}'
CREATE_PERMISSION='mutation($actor:ID!,$input:CreatePermissionInput!){createPermission(actorCompanyUserId:$actor,input:$input){id code name description isActive}}'
DEACTIVATE_ROLE='mutation($actor:ID!,$id:ID!){deactivateRole(actorCompanyUserId:$actor,id:$id){id isActive}}'
MEMBERS='query($actor:ID!,$id:ID!){companyUsers(actorCompanyUserId:$actor,companyId:$id){id isAdmin isActive user{id}}}'
ACCOUNTS='query($actor:ID!,$id:ID!,$type:AccountType,$active:Boolean){accounts(actorCompanyUserId:$actor,companyId:$id,accountType:$type,activeOnly:$active){id name isActive}}'
CONCEPTS='query($actor:ID!,$id:ID!,$type:ConceptType,$active:Boolean){concepts(actorCompanyUserId:$actor,companyId:$id,conceptType:$type,activeOnly:$active){id name isActive}}'
